"""Place the basketball south sidewalk directly against the existing road edge."""
import json,subprocess
from pathlib import Path
from shapely.geometry import Polygon
from shapely.ops import unary_union
root=Path(__file__).resolve().parents[1];c=json.loads((root/'data/campus.json').read_text());a=json.loads((root/'facilities/sports-courts/south-sidewalk.json').read_text())
js="""import fs from'node:fs';import{createRoadNetwork}from'./roads.js';import{sidewalkSections}from'./site-physics.js';import{routeSections}from'./pavement.js';const c=JSON.parse(fs.readFileSync('data/campus.json'));c.sidewalkRoadIds=[218881799];c.sidewalkSides={...c.sidewalkSides,218881799:[-1]};const n=createRoadNetwork(c.roads,()=>0,{}, {pavedAreas:c.pavedAreas,junctionFillets:c.junctionFillets}),a=[34.4,-136.6],b=[92.8,-169],dx=b[0]-a[0],dz=b[1]-a[1],project=p=>((p[0]-a[0])*dx+(p[1]-a[1])*dz)/(dx*dx+dz*dz),polygons=sidewalkSections(c,n).filter(s=>s.road===218881799).map(s=>s.points).filter(p=>{const m=p.reduce((s,q)=>[s[0]+q[0]/p.length,s[1]+q[1]/p.length],[0,0]);return project(m)>=0&&project(m)<=1;});const centre=routeSections(n.routes.find(r=>r.osm===218881799)).filter(p=>project([p.x,p.z])<=1).map(p=>[p.x-p.nx*(p.width/2+1.8),p.z-p.nz*(p.width/2+1.8)]);process.stdout.write(JSON.stringify({polygons,centre}));"""
q=json.loads(subprocess.check_output(['node','--input-type=module','-e',js],cwd=root));shape=unary_union([Polygon(r)for r in q['polygons']]).buffer(0);assert shape.geom_type=='Polygon';ring=[[round(x,7),round(z,7)]for x,z in list(shape.exterior.coords)[:-1]]
path=root/'facilities/campus-plazas/layout.json';layout=json.loads(path.read_text());layout['pedestrianAreas']=[p for p in layout['pedestrianAreas']if p['id']!=a['id']]+[dict(id=a['id'],name=a['name'],ring=ring,width=a['width'],connection='S09',connectionRoad=a['connectionRoad'],reference=a['reference'])];path.write_text(json.dumps(layout,ensure_ascii=False,indent=2)+'\n')
c['roads']=[r for r in c['roads']if r['osm']!=a['removeFootpath']['osm']];c['courtSouthSidewalk']={**a,'ring':ring,'centerLine':q['centre']};(root/'data/campus.json').write_text(json.dumps(c,ensure_ascii=False,separators=(',',':'))+'\n');print('Built road-edge south sidewalk, directly touching the north side of road 218881799')
